(p/'backend.test.js').write_text('''import test from 'node:test';
import assert from 'node:assert/strict';
import { BatchPricingPolicy } from '../../FreshFood.Reposistory/Entities/BatchPricingPolicy.js';
import { DeliveryFeePolicy } from '../../FreshFood.Reposistory/Entities/DeliveryFeePolicy.js';
import { UnitOfWork } from '../../FreshFood.Reposistory/Repository/Implements/UnitOfWork.js';
import { Cart } from '../../FreshFood.Reposistory/Entities/Cart.js';
import { CurrentCustomer } from '../Services/Implements/CurrentCustomer.js';
import { CatalogService } from '../Services/Implements/CatalogService.js';
import { CartService } from '../Services/Implements/CartService.js';
import { ProfileService } from '../Services/Implements/ProfileService.js';
import { CheckoutService } from '../Services/Implements/CheckoutService.js';
import { MyOrdersService } from '../Services/Implements/MyOrdersService.js';
import { TransitionExecutor } from '../Services/Implements/TransitionExecutor.js';
import { AcceptOrderTransition } from '../Services/Implements/AcceptOrderTransition.js';
import { EnterPendingUnpaidTransition } from '../Services/Implements/EnterPendingUnpaidTransition.js';
import { InitializeUnpaidPaymentTransition } from '../Services/Implements/InitializeUnpaidPaymentTransition.js';
import { CancelPendingUnpaidTransition } from '../Services/Implements/CancelPendingUnpaidTransition.js';
import { trustedSnapshot } from '../Services/Implements/transitionRuntime.js';
import { createRequestScope } from '../composition.js';
import { createApiServer } from '../http.js';
import { CatalogRepository } from '../../FreshFood.Reposistory/Repository/Implements/CatalogRepository.js';
const pricing=new BatchPricingPolicy();const now=()=>new Date();
const batch=(extra={})=>({BatchId:'1',ProductId:'1',CurrentStock:10,ReservedStock:0,ExpiryDate:'2099-01-01',RetailPrice:'10000',DiscountRate:'0',SaleStatus:'ACTIVE',...extra});
const product={ProductId:'1',ProductName:'Organic greens',UnitOfMeasure:'pack',Description:'Fresh greens',IsActive:true};
const identity=new CurrentCustomer({CustomerId:'7'});
function uow(){const events=[];return {events,unit:new UnitOfWork({async BeginAsync(){events.push('begin');},async CommitAsync(){events.push('commit');},async RollbackAsync(){events.push('rollback');}})};}
for(const [distance,fee] of [[0,'10000'],[0.999,'10000'],[1,'20000'],[2.999,'20000'],[3,'30000'],[10,'30000']])test('delivery boundary '+distance,()=>assert.equal(new DeliveryFeePolicy().Quote(distance).toString(),fee));
for(const bad of [-1,NaN,Infinity,10.001])test('delivery rejects '+bad,()=>assert.throws(()=>new DeliveryFeePolicy().Quote(bad)));
for(const [rate,value] of [['0','10000'],['10','9000'],['50','5000'],['10.25','8975']])test('exact VND discount '+rate,()=>assert.equal(pricing.Quote(batch({DiscountRate:rate}),now()).toString(),value));
test('fractional VND does not silently round',()=>assert.throws(()=>pricing.Quote(batch({RetailPrice:'10001',DiscountRate:'10'}),now()),{code:'ROUNDING_POLICY_TBD'}));
test('expired batch is rejected',()=>assert.throws(()=>pricing.Quote(batch({ExpiryDate:'2000-01-01'}),now())));
test('money beyond JS safe integer stays exact',()=>assert.equal(pricing.Quote(batch({RetailPrice:'90071992547409930'}),now()).toString(),'90071992547409930'));
test('transaction rolls back and preserves original error',async()=>{const x=uow();await assert.rejects(x.unit.ExecuteAsync(async()=>{throw new Error('failed');}),/failed/);assert.deepEqual(x.events,['begin','rollback']);});
test('aborted operation never starts transaction',async()=>{const x=uow(),c=new AbortController();c.abort();await assert.rejects(x.unit.ExecuteAsync(async()=>{},c.signal));assert.deepEqual(x.events,[]);});
test('catalog empty search returns six alternatives',async()=>{let limit;const repo={async FindActiveAsync(){return [];},async GetCategoriesAsync(){return [];},async GetPopularAsync(n){limit=n;return [product];},async GetSellableBatchesAsync(){return [batch()];}};const result=await new CatalogService(repo,pricing).SearchAsync({Keyword:'none'});assert.equal(limit,6);assert.equal(result.Items.length,0);assert.equal(result.Alternatives[0].CurrentPrice,'10000');});
test('catalog does not expose delisted product detail',async()=>{const repo={async GetProductAsync(){return {...product,IsActive:false};}};await assert.rejects(new CatalogService(repo,pricing).GetProductDetailsAsync('1'),{code:'NOT_FOUND'});});
function cartFixture(stock=10){const c=new Cart({CartId:'1',Items:[]});const x=uow();const repo={async GetAsync(){return c;},async GetProductsAsync(){return [product];},async GetSellableBatchesAsync(){return [batch({CurrentStock:stock})];},async SaveAsync(){}};return {c,x,service:new CartService(repo,identity,x.unit,pricing)};}
test('cart clamps requested quantity to live stock',async()=>{const f=cartFixture(3);const result=await f.service.ChangeQuantityAsync({ProductId:'1',Quantity:5});assert.equal(result.Lines[0].Quantity,3);assert.equal(result.SubTotal,'30000');assert.deepEqual(result.Warnings,['QUANTITY_CLAMPED:1']);assert.deepEqual(f.x.events,['begin','commit']);});
for(const q of [0,-1,1.5,NaN])test('cart rejects quantity '+q,async()=>await assert.rejects(cartFixture().service.ChangeQuantityAsync({ProductId:'1',Quantity:q}),{code:'INVALID_QUANTITY'}));
test('cart identity is server resolved',async()=>{let used;const repo={async GetAsync(c,s){used={c,s};return new Cart();},async GetProductsAsync(){return [];},async GetSellableBatchesAsync(){return [];}};await new CartService(repo,identity,uow().unit,pricing).GetCartAsync({CustomerId:'attacker'});assert.equal(used.c,'7');});
test('cart marks expired or missing batch not check-outable',async()=>{const f=cartFixture(0);f.c.ChangeQuantity('1',2);const r=await f.service.GetCartAsync();assert.equal(r.CanCheckout,false);assert.equal(r.Warnings[0],'UNAVAILABLE:1');});
test('remove item returns recalculated empty cart',async()=>{const f=cartFixture();f.c.ChangeQuantity('1',2);const r=await f.service.RemoveItemAsync('1');assert.deepEqual(r.Lines,[]);assert.equal(r.SubTotal,'0');});
function profileFixture(){let saved;const x=uow();const repo={async GetCustomerAsync(){return {CustomerId:'7',FullName:'Tester',Phone:'0901234567'};},async GetAddressesAsync(){return [{AddressId:'2',CustomerId:'7',RecipientName:'A',RecipientPhone:'0901234567',StreetAddress:'Street',Latitude:10,Longitude:106,IsDefault:false}];},async SaveCustomerAsync(c){saved=c;},async SaveAddressAsync(a){saved=a;},async HasActiveOrderAsync(){return true;},async DeleteAddressAsync(){throw new Error('must not delete');}};return {repo,x,get saved(){return saved;},service:new ProfileService(repo,identity,x.unit,{async ResolveAsync(){return {Latitude:10,Longitude:106};}})};}
test('profile updates only name/email, never trusted customer identity',async()=>{const f=profileFixture();await f.service.UpdateProfileAsync({FullName:'New name',Email:'a@example.com',CustomerId:'8'});assert.equal(f.saved.CustomerId,'7');assert.equal(f.saved.FullName,'New name');});
test('profile rejects malformed email before write',async()=>await assert.rejects(profileFixture().service.UpdateProfileAsync({FullName:'A',Email:'bad'}),{code:'INVALID_EMAIL'}));
test('address ownership rejects another customers address',async()=>await assert.rejects(profileFixture().service.SaveAddressAsync({AddressId:'99',RecipientName:'A',RecipientPhone:'0901234567',StreetAddress:'Street'}),{code:'NOT_FOUND'}));
test('address used by active order cannot be deleted',async()=>{const f=profileFixture();await assert.rejects(f.service.DeleteAddressAsync('2'),{code:'ADDRESS_USED_BY_ACTIVE_ORDER'});assert.deepEqual(f.x.events,['begin','rollback']);});
function orderFixture(){const state={events:new Set(),orders:[],batches:[batch()],cart:new Cart({CartId:'1',Items:[{ProductId:'1',Quantity:3}]}),notifications:[]};let snapshot;const unit=new UnitOfWork({async BeginAsync(){snapshot=structuredClone({...state,cart:{...state.cart,Items:state.cart.Items}});},async CommitAsync(){},async RollbackAsync(){Object.assign(state,snapshot);state.cart=new Cart(state.cart);}});const lifecycle={async RecordEventOnceAsync(a,e,t){const key=[a,e,t].join('|');if(state.events.has(key))return false;state.events.add(key);return true;}};const transitions=[new AcceptOrderTransition(lifecycle),new EnterPendingUnpaidTransition(lifecycle),new InitializeUnpaidPaymentTransition(lifecycle)];const executor=new TransitionExecutor(transitions,unit,lifecycle);
 const repo={async GetCheckoutCartAsync(){return state.cart;},async GetOwnedAddressAsync(){return {AddressId:'2',CustomerId:'7'};},async LockFefoBatchesAsync(){return state.batches;},async SaveOrderAsync(o){for(const l of o.Details){const b=state.batches.find(b=>b.BatchId===l.BatchId);assert.ok(b.CurrentStock-b.ReservedStock>=l.Quantity);b.ReservedStock+=l.Quantity;}o.OrderId=String(state.orders.length+1);state.orders.push(o);},async ClearCartAsync(){state.cart.Items=[];}};
 const service=new CheckoutService(repo,identity,unit,{async CalculateAsync(){return 1;}},{},{async PublishAsync(n){state.notifications.push(n);}},executor,pricing,new DeliveryFeePolicy());return {state,repo,service};}
const orderRequest={AddressId:'2',PaymentMethod:'Cod',CheckoutReference:'checkout-1',IdempotencyKey:'event-1'};
test('checkout accepts COD through acceptOrder and independent unpaid branch',async()=>{const f=orderFixture();const r=await f.service.PlaceOrderAsync(orderRequest);assert.equal(r.Status,'PendingUnpaid');assert.equal(r.PaymentStatus,'Unpaid');assert.equal(r.Total,'50000');assert.equal(f.state.batches[0].ReservedStock,3);assert.equal(f.state.cart.Items.length,0);assert.equal(f.state.events.size,3);assert.equal(f.state.notifications.length,1);});
test('checkout FEFO splits quantities over ordered batches',async()=>{const f=orderFixture();f.state.batches=[batch({BatchId:'2',CurrentStock:10,ExpiryDate:'2099-02-01',RetailPrice:'20000'}),batch({CurrentStock:2})];const r=await f.service.PrepareCheckoutAsync({AddressId:'2'});assert.deepEqual(r.Lines.map(l=>[l.BatchId,l.Quantity]),[['1',2],['2',1]]);assert.equal(r.Total,'60000');});
test('checkout insufficient stock writes nothing',async()=>{const f=orderFixture();f.state.batches[0].CurrentStock=1;await assert.rejects(f.service.PlaceOrderAsync(orderRequest),{code:'INSUFFICIENT_STOCK'});assert.equal(f.state.orders.length,0);assert.equal(f.state.events.size,0);});
test('checkout persistence failure rolls back reservation and all transition evidence',async()=>{const f=orderFixture();f.repo.ClearCartAsync=async()=>{throw new Error('storage failed');};await assert.rejects(f.service.PlaceOrderAsync(orderRequest),/storage failed/);assert.equal(f.state.orders.length,0);assert.equal(f.state.batches[0].ReservedStock,0);assert.equal(f.state.events.size,0);assert.equal(f.state.notifications.length,0);});
test('prepaid flow fails closed while correlation policy remains TBD',async()=>await assert.rejects(orderFixture().service.PlaceOrderAsync({...orderRequest,PaymentMethod:'VietQr'}),{code:'PRE_ACCEPTANCE_PAYMENT_CORRELATION_TBD'}));
test('forged transition snapshot is rejected',async()=>{const x=new TransitionExecutor([],uow().unit,{});await assert.rejects(x.ExecuteInCurrentTransactionAsync({AggregateId:'1'},{AggregateId:'1',TransitionId:'T01p'}),{code:'UNTRUSTED_TRANSITION'});});
test('cancellation cannot run from Packing',async()=>{const repo={async LockOwnedAsync(){return {OrderId:'1',OrderStatus:'Packing'};}};const service=new MyOrdersService(repo,identity,uow().unit,{}, {},pricing);await assert.rejects(service.CancelOrderAsync({OrderId:'1',Reason:'changed mind'}),{code:'CANCELLATION_NOT_ALLOWED'});});
test('review enforces Delivered and 1..5 rating',async()=>{const service=new MyOrdersService({async LockOwnedAsync(){return {OrderStatus:'Shipping'};}},identity,uow().unit,{}, {},pricing);await assert.rejects(service.SubmitReviewAsync({OrderId:'1',Rating:0}),{code:'RATING_OUT_OF_RANGE'});await assert.rejects(service.SubmitReviewAsync({OrderId:'1',Rating:5}),{code:'REVIEW_REQUIRES_DELIVERED'});});
test('history and detail are restricted to authenticated owner',async()=>{let customer;const service=new MyOrdersService({async FindOwnedAsync(id){customer=id;return [];}},identity,uow().unit,{},{},pricing);assert.deepEqual(await service.GetOrdersAsync(),{Orders:[]});await assert.rejects(service.GetOrderDetailsAsync('other'),{code:'NOT_FOUND'});assert.equal(customer,'7');});
test('SQL search binds malicious keyword as data',async()=>{let sql,args;const repo=new CatalogRepository({connection:{async QueryAsync(s,a){sql=s;args=a;return {rows:[]};}}});const keyword="x' OR TRUE --";await repo.FindActiveAsync(keyword,null,false);assert.equal(args[0],keyword);assert.ok(!sql.includes(keyword));assert.match(sql,/\\$1/);});
test('DI resolves all five controllers and exactly 24 transition handlers',()=>{const scope=createRequestScope({connection:{async QueryAsync(){return {rows:[]};}},principal:{CustomerId:'7'},transport:{async SendAsync(){throw new Error('external gateway disabled in test');}}});for(const n of ['Catalog','Cart','Profile','Checkout','MyOrders'])assert.ok(scope.Resolve(n+'Controller').service);const handlers=scope.ResolveMany('IStateTransition');assert.equal(handlers.length,24);assert.equal(new Set(handlers.map(x=>x.Id)).size,24);});
test('HTTP exposes JSON, blocks malformed payload and does not trust identity fields',async t=>{const received=[];const server=createApiServer({authenticate:async()=>({CustomerId:'7'}),scopeFactory:async principal=>({Resolve:()=>({async UpdateProfileAsync(request){received.push({request,principal});return {CustomerId:principal.CustomerId};}})})});await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));t.after(()=>new Promise(resolve=>server.close(resolve)));const url='http://127.0.0.1:'+server.address().port;let r=await fetch(url+'/health');assert.equal(r.status,200);r=await fetch(url+'/api/profile',{method:'PATCH',body:'{bad'});assert.equal(r.status,400);r=await fetch(url+'/api/profile',{method:'PATCH',body:JSON.stringify({FullName:'A',CustomerId:'999'})});assert.deepEqual(await r.json(),{CustomerId:'7'});assert.equal(received.length,1);});
''',encoding='utf-8')
print('Created functional unit/module tests for five use cases, boundaries, rollback, DI and HTTP')
